"""Build reviewable reports from canonical evidence; missing evidence stays explicit."""
import sys,json,hashlib,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT));OUT=Path(__file__).resolve().parent
REPORT=ROOT/'development/campaigns/product_realization/pr_play_69'
def read(n):return json.loads((OUT/n).read_text(encoding='utf-8'))
def save(n,v):(OUT/n).write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    REPORT.mkdir(parents=True,exist_ok=True)
    baseline=read('baseline.json');reg=read('regression_summary.json');metrics=read('metrics.json');hold=read('holdout_summary.json')
    state=read('state_integrity.json');live=read('live_results.json')['rows'];classified=read('live_candidate_classification.json')
    previous=set()
    for raw,row in zip(live,classified):
        journal=raw['body']['journal']['discovered_clues'];current=set(journal)
        row.pop('new_journal_discoveries',None)
        row.update(new_discovery_count=len(current-previous),existing_discovery_count=len(current & previous),
            journal_discoveries=journal,resolver_disclosures=(raw['trace'].get('hook_input') or {}).get('resolution',{}).get('discovered_clues',[]))
        previous=current
    save('live_candidate_classification.json',classified)
    forbidden={'gm_notes','hidden_facts','private_notes','discoverable_clues','gm_only','validation','raw_provider_text','narration_payload','hidden_event_triggers'}
    def fields(v):
        if isinstance(v,dict):return set(v).intersection(forbidden)|set().union(*(fields(x) for x in v.values()),set())
        if isinstance(v,list):return set().union(*(fields(x) for x in v),set())
        return set()
    scan=[dict(input=r['input'],bytes=r['bytes'],hidden_sentinels=r['hidden_exposures'],forbidden_fields=sorted(fields(r['body']))) for r in live]
    save('complete_payload_scan.json',dict(responses=scan,exposures=sum(len(r['hidden_sentinels'])+len(r['forbidden_fields']) for r in scan),
        hidden_server_state_retained=all(r['authority_after']['session']['gm_notes']==['CANARY_GM_NOTE'] for r in live)))
    freeze=read('implementation_freeze.json')
    save('freeze_integrity.json',dict(unchanged=all(sha(ROOT/n)==v for n,v in freeze.items()),files=freeze,
        holdout_hash_matches=sha(OUT/'frozen_holdout.json')==read('frozen_holdout_manifest.json')['sha256']))
    protected=baseline['protected'];changed=[n for n,v in protected.items() if not (ROOT/n).exists() or sha(ROOT/n)!=v]
    save('protected_integrity.json',dict(files=len(protected),changed=changed))
    assert not changed,'Protected entry evidence changed; investigate before export'
    assert state['passed'] and read('complete_payload_scan.json')['exposures']==0
    dev=__import__('xml.etree.ElementTree',fromlist=['parse']).parse(OUT/'development.xml').getroot().find('testsuite').attrib
    save('test_summary.json',dict(development=dev,holdout=hold,regression=reg))
    hold_results=read('holdout_results.json')
