    action_table='\n\n'.join(f"Action {n+1}: `{r['input']}`\n\nCandidate: {r['candidate'] or '[no provider: deterministic movement]'}\n\nPublished response: {r['final']}\n\nDecision: {r['publication'] or 'deterministic movement'}; new journal entries: {r['new_discovery_count']}; existing entries: {r['existing_discovery_count']}." for n,r in enumerate(classified))
